pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // Ensure oracleVersion is within reasonable bounds
        vm.assume(oracleVersion <= 100);

        // Record the price from atVersion before sync
        (bool successBefore, bytes memory dataBefore) = address(c).staticcall(
            abi.encodeWithSignature("atVersion(uint256)", oracleVersion)
        );
        if (!successBefore) return; // skip if revert (e.g., version not available)

        // Decode result (OracleVersion is a struct with version, timestamp, price)
        (uint256 versionBefore, uint256 timestampBefore, int256 priceBefore) = abi.decode(dataBefore, (uint256, uint256, int256));

        // Try to sync (might revert on non-contract oracle in mutant)
        (bool syncSuccess, ) = address(c).call(abi.encodeWithSignature("sync()"));

        // Get price after sync (if possible)
        (bool successAfter, bytes memory dataAfter) = address(c).staticcall(
            abi.encodeWithSignature("atVersion(uint256)", oracleVersion)
        );

        // Rule: If both calls succeed, the price should be the same (no oracle change)
        if (successBefore && successAfter) {
            (uint256 versionAfter, uint256 timestampAfter, int256 priceAfter) = abi.decode(dataAfter, (uint256, uint256, int256));
            assertTrue(priceBefore == priceAfter, "Price changed after sync");
        }
    }
}

