pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 oracleVersion) public {
        // Bound the oracle version to avoid enormous storage reads
        oracleVersion = bound(oracleVersion, 0, 100);

        // If oracleVersion is 0, the oracle might not have a version stored; skip
        vm.assume(oracleVersion > 0);

        // Call atVersion to get the transformed price
        (uint256 version, uint256 timestamp, int256 price) = c.atVersion(oracleVersion);

        // Get the original oracle price by calling the oracle directly
        (uint256 origVersion, uint256 origTimestamp, int256 origPrice) = c.oracle().atVersion(oracleVersion);

        // The rule: after payoff transformation, the absolute value of the price should be <= original absolute price * 100
        // This holds for any reasonable payoff transformation that doesn't wildly amplify prices
        bool transformedReducesMagnitude = abs(price) <= abs(origPrice) * 100;

        assertTrue(transformedReducesMagnitude, "Price transformation should not amplify beyond 100x");
    }

    function abs(int256 x) private pure returns (uint256) {
        return x >= 0 ? uint256(x) : uint256(-x);
    }
}

