pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        // The reference contract (P) has a valid controller; the buggy one (M) has address(0).
        // atVersion eventually calls oracle().atVersion(). oracle() uses the controller to check if the oracle is a contract.
        // If controller() returns address(0), the oracle address check might still pass if it's not zero, but the call will revert because address(0) is not a contract.
        // However, the actual bug is that controller() returns address(0), which makes isContract() fail for the controller itself, causing a revert in the internal call.
        // To test this, we need to ensure that a call to atVersion either succeeds or reverts consistently with the expected behavior.
        // For the reference P, atVersion should succeed (or revert with a different error). For M, it should revert because of the zero controller.
        vm.assume(oracleVersion <= 1000000); // avoid excessive gas
        // We need a real oracle to be set. The simplest approach is to check that controller() is not zero.
        // Since we cannot directly check internal state, we rely on the fact that atVersion will revert if controller is zero.
        try c.atVersion(oracleVersion) {
            // If atVersion succeeds, then controller must be non-zero (reference behavior).
            assertTrue(address(c.controller()) != address(0), "controller should not be zero");
        } catch {
            // If atVersion reverts, we cannot distinguish between different causes here,
            // but the buggy version will always revert because controller is zero.
            // So we just assert that controller is zero (which is the buggy behavior).
            // However, this test is meant to FAIL on the buggy version, so we need an assertion that fails for the buggy version.
            // The general rule: atVersion should NOT revert when the oracle is properly set.
            // Since we cannot control the oracle, we use the fact that in the reference, controller() is non-zero.
            // This test will fail if atVersion reverts, which is the buggy behavior.
            assertTrue(false, "atVersion should not revert with a valid controller");
        }
    }
}

